      "keystrokes": "printf '%s\\n' '#!/usr/bin/env python3' 'import json, hashlib, hmac' 'from pathlib import Path' '' 'INPUT_DIR = Path(\"input\")' 'OUTPUT_DIR = Path(\"workspace\")' 'SECRET_KEY = b\"CLAUDITOR_SECRET_KEY_2025\"' '' 'def compute_hmac(data, key):' '    return hmac.new(key, data.encode(\"utf-8\"), hashlib.sha256).hexdigest()' '' 'events = []' 'for line in (INPUT_DIR / \"events.log\").read_text().strip().split(chr(10)):' '    if line.strip():' '        events.append(json.loads(line))' '' 'chain = []' 'prev_hash = \"genesis\"' 'for i, event in enumerate(events):' '    event_str = json.dumps(event, sort_keys=True)' '    chain_input = prev_hash + \"|\" + event_str' '    current_hash = compute_hmac(chain_input, SECRET_KEY)' '    chain.append({' \"        'index': i,\" \"        'timestamp': event['ts'],\" \"        'event_type': event['event'],\" \"        'path': event['path'],\" \"        'marker': event['marker'],\" \"        'hmac': current_hash,\" \"        'prev_hash': prev_hash\" \"    })\" '    prev_hash = current_hash' '' 'marker = (INPUT_DIR / \"expected_marker.txt\").read_text().strip()' 'template = json.loads((INPUT_DIR / \"summary_template.json\").read_text())' '' 'summary = {' \"    'title': template['title'],\" \"    'version': template['version'],\" \"    'marker': marker,\" \"    'event_count': len(events),\" \"    'chain': chain,\" \"    'root_hash': chain[-1]['hmac'] if chain else 'empty',\" \"    'verification': {\" \"        'instructions': 'Verify chain by recomputing HMACs sequentially.'\" \"    }\" \"}\" '' '(OUTPUT_DIR / \"audit_summary.json\").write_text(json.dumps(summary, indent=2) + chr(10))' 'print(\"Summary created with\", len(events), \"events\")' 'print(\"Root hash:\", summary[\"root_hash\"])' > workspace/create_summary.py\n",
